import React, { useState, useRef } from 'react';
import axios from 'axios';

// --- UI Icons ---
const UploadIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
    </svg>
);

const SparklesIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M5 3v4M3 5h4M19 3v4M17 5h4M14 11l-1.5 1.5L11 14l-1.5-1.5L8 11l1.5-1.5L11 8l1.5 1.5L14 11zM19 19v-4M17 19h4" />
    </svg>
);


function FileUpload() {
  // --- State for File Upload ---
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [parentFolderId, setParentFolderId] = useState('');
  const fileInputRef = useRef(null);

  // --- State for Gemini AI Features ---
  const [filePreview, setFilePreview] = useState(null); // For image previews or text content
  const [fileTypeForAi, setFileTypeForAi] = useState(''); // 'image' or 'text'
  const [isGenerating, setIsGenerating] = useState(false);
  const [geminiResponse, setGeminiResponse] = useState(null);
  const [geminiError, setGeminiError] = useState('');


  // --- Environment Variable Check ---
  if (!import.meta.env.VITE_API_URL) {
    return (
        <div className="card p-6 shadow-lg rounded-xl bg-red-50 border-red-500 text-red-800 max-w-xl mx-auto mt-8">
          <h2 className="text-2xl font-bold mb-4">Configuration Error</h2>
          <p className="font-semibold">The API URL is not configured.</p>
          <p className="mt-2">Please ensure you have a <code className="bg-red-200 p-1 rounded">.env</code> file in your project's root directory with the following content:</p>
          <pre className="bg-red-200 p-2 rounded mt-2 text-sm">VITE_API_URL=http://localhost:8080</pre>
          <p className="mt-4 font-bold">After creating or editing the <code className="bg-red-200 p-1 rounded">.env</code> file, you MUST restart your development server.</p>
        </div>
    );
  }

  // --- File Selection and Preview Handler ---
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    // Reset everything on new file selection
    setFile(null);
    setFilePreview(null);
    setFileTypeForAi('');
    setGeminiResponse(null);
    setGeminiError('');
    setMessage('');
    setError('');

    if (!selectedFile) return;

    setFile(selectedFile);
    const reader = new FileReader();

    if (selectedFile.type.startsWith('image/')) {
      setFileTypeForAi('image');
      reader.onloadend = () => {
        // result contains the base64-encoded string
        setFilePreview(reader.result);
      };
      reader.readAsDataURL(selectedFile);
    } else if (selectedFile.type.startsWith('text/')) {
      setFileTypeForAi('text');
      reader.onloadend = () => {
        setFilePreview(reader.result);
      };
      reader.readAsText(selectedFile);
    } else {
      setFileTypeForAi('other');
    }
  };

  const handleParentFolderChange = (e) => {
    setParentFolderId(e.target.value);
  };

  // --- Gemini API Call ---
  const handleGeminiAction = async () => {
    if (!filePreview) {
      setGeminiError('No file content to analyze.');
      return;
    }

    setIsGenerating(true);
    setGeminiResponse(null);
    setGeminiError('');

    const apiKey = ""; // Will be handled by the environment
    const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${apiKey}`;

    let payload;
    if (fileTypeForAi === 'image') {
      const base64Data = filePreview.split(',')[1];
      payload = {
        contents: [{
          role: "user",
          parts: [
            { text: "Describe this image in detail. What is happening, who are the subjects, and what is the background?" },
            { inlineData: { mimeType: file.type, data: base64Data } }
          ]
        }]
      };
    } else if (fileTypeForAi === 'text') {
      payload = {
        contents: [{
          role: "user",
          parts: [{ text: `Summarize the following text and suggest a concise, descriptive filename (without extension). Respond with a JSON object containing "summary" and "suggestedFilename" keys.\n\n---\n\n${filePreview}` }]
        }],
        generationConfig: {
          responseMimeType: "application/json",
        }
      };
    } else {
      setGeminiError("Cannot analyze this file type.");
      setIsGenerating(false);
      return;
    }

    try {
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        throw new Error(`API request failed with status ${response.status}`);
      }

      const result = await response.json();
      const text = result.candidates[0]?.content?.parts[0]?.text;

      if (text) {
        setGeminiResponse(text);
      } else {
        throw new Error("Received an empty response from the API.");
      }

    } catch (err) {
      console.error("Gemini API Error:", err);
      setGeminiError(`Failed to get analysis. ${err.message}`);
    } finally {
      setIsGenerating(false);
    }
  };


  // --- Main File Upload Handler ---
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!file) {
      setError('Please select a file to upload.');
      return;
    }
    // ... (rest of the submit logic is unchanged)
    setLoading(true);
    setMessage('');
    setError('');
    const formData = new FormData();
    formData.append('file', file);
    if (parentFolderId) {
      formData.append('parentFolderId', parentFolderId);
    }
    try {
      const uploadApiUrl = `${import.meta.env.VITE_API_URL}/api/files/upload`;
      await axios.post(uploadApiUrl, formData, { headers: { 'Content-Type': 'multipart/form-data' } });
      setMessage('File uploaded successfully!');
      setFile(null);
      setParentFolderId('');
      setFilePreview(null);
      setFileTypeForAi('');
      setGeminiResponse(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
      window.dispatchEvent(new CustomEvent('fileUploaded'));
    } catch (err) {
      if (err.response) setError(err.response.data.message || 'Failed to upload file.');
      else if (err.request) setError('No response from server. Check network.');
      else setError('Unexpected error occurred.');
      console.error('Error uploading file:', err);
    } finally {
      setLoading(false);
    }
  };

  // --- Render Component ---
  return (
      <div className="font-sans bg-gray-50 flex items-center justify-center p-4">
        <div className="card p-6 shadow-lg rounded-xl bg-white max-w-2xl w-full mx-auto">
          <h2 className="text-2xl font-bold mb-5 text-gray-800 border-b pb-3">Upload New File</h2>

          {message && <div className="p-3 mb-4 rounded-lg bg-green-100 text-green-800 border border-green-200">{message}</div>}
          {error && <div className="p-3 mb-4 rounded-lg bg-red-100 text-red-800 border border-red-200">{error}</div>}

          <form onSubmit={handleSubmit} noValidate>
            <div className="mb-4">
              <label htmlFor="fileInput" className="block font-medium text-gray-700 mb-1">Select File</label>
              <input type="file" id="fileInput" ref={fileInputRef} className="form-control file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-violet-50 file:text-violet-700 hover:file:bg-violet-100 block w-full text-sm text-gray-500 border rounded-lg cursor-pointer focus:outline-none" onChange={handleFileChange} />
            </div>

            {/* --- Gemini AI Section --- */}
            {filePreview && (fileTypeForAi === 'image' || fileTypeForAi === 'text') && (
                <div className="my-5 p-4 border rounded-lg bg-gray-50">
                  <h3 className="text-lg font-semibold text-gray-700 mb-3">AI Analysis ✨</h3>
                  {fileTypeForAi === 'image' && <img src={filePreview} alt="Selected preview" className="rounded-lg max-h-60 mx-auto mb-3" />}
                  {fileTypeForAi === 'text' && <textarea readOnly value={filePreview} className="w-full h-32 p-2 border rounded bg-white text-sm text-gray-600" />}

                  <button type="button" onClick={handleGeminiAction} disabled={isGenerating} className="mt-2 w-full flex items-center justify-center btn bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:bg-gray-400 transition-colors">
                    <SparklesIcon />
                    {isGenerating ? 'Analyzing...' : (fileTypeForAi === 'image' ? 'Generate Description' : 'Summarize & Suggest Title')}
                  </button>

                  {geminiError && <div className="mt-3 p-2 rounded-lg bg-red-100 text-red-700 text-sm">{geminiError}</div>}

                  {geminiResponse && (
                      <div className="mt-4 p-3 bg-blue-50 border-l-4 border-blue-500 rounded-r-lg">
                        <h4 className="font-bold text-blue-800">Analysis Result:</h4>
                        {(() => {
                          try {
                            const jsonResponse = JSON.parse(geminiResponse);
                            return (
                                <>
                                  <p className="mt-2 text-gray-700"><strong>Summary:</strong> {jsonResponse.summary}</p>
                                  <p className="mt-1 text-gray-700"><strong>Suggested Title:</strong> <code className="bg-blue-200 text-blue-900 p-1 rounded">{jsonResponse.suggestedFilename}</code></p>
                                </>
                            );
                          } catch (e) {
                            return <p className="mt-2 text-gray-700 whitespace-pre-wrap">{geminiResponse}</p>;
                          }
                        })()}
                      </div>
                  )}
                </div>
            )}

            <div className="mb-6">
              <label htmlFor="parentFolderId" className="block font-medium text-gray-700 mb-1">Parent Folder ID (Optional)</label>
              <input type="text" id="parentFolderId" value={parentFolderId} onChange={handleParentFolderChange} className="form-control border rounded-lg p-2 w-full focus:ring-2 focus:ring-violet-500 focus:border-violet-500 outline-none" placeholder="Leave empty to upload to root" />
            </div>

            <button type="submit" className={`w-full flex items-center justify-center btn bg-violet-600 text-white px-4 py-2.5 rounded-lg hover:bg-violet-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-violet-500 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors duration-300`} disabled={loading || !file}>
              <UploadIcon />
              {loading ? 'Uploading...' : 'Upload File'}
            </button>
          </form>
        </div>
      </div>
  );
}

export default FileUpload;
